async fn down(&self, manager: &SchemaManager) -> Result<(), DbErr> { manager .drop_table(Table::drop().table(FileSession::Table).to_owned()) .await } }
#[derive(DeriveIden)] enum FileSession { Table, Id, SessionId, FileName, FileSize, UploadedSize, Status, CreatedAt, UpdatedAt, }

