use actix_web::{get, HttpResponse, Result};
use crate::services::main_service::MainService;

#[get("/api/hello")]
pub async fn hello() -> Result<HttpResponse> {
    let message = MainService::get_hello_message().await;
    Ok(HttpResponse::Ok().json(serde_json::json!({
        "message": message
    })))
}

use actix_web::{web, HttpResponse, Result};
use crate::services::main_service::MainService;
use crate::models::user_models::{CreateUserRequest, CreateUserResponse};

pub async fn hello() -> Result<HttpResponse> {
    let message = MainService::get_hello_message().await;
    Ok(HttpResponse::Ok().json(serde_json::json!({
        "message": message
    })))
}

pub async fn welcome(path: web::Path<String>) -> Result<HttpResponse> {
    let name = path.into_inner();
    let message = MainService::get_welcome_message(&name).await;
    Ok(HttpResponse::Ok().json(serde_json::json!({
        "message": message
    })))
}

pub async fn create_user(req: web::Json<CreateUserRequest>) -> Result<HttpResponse> {
    let user_data = req.into_inner();
    let response = MainService::create_user(user_data.name, user_data.email).await;

    Ok(HttpResponse::Created().json(response))
}

pub async fn update_message(req: web::Json<serde_json::Value>) -> Result<HttpResponse> {
    let new_message = req.get("message")
        .and_then(|v| v.as_str())
        .unwrap_or("Default message");

    let result = MainService::update_message(new_message).await;

    Ok(HttpResponse::Ok().json(serde_json::json!({
        "success": true,
        "message": result
    })))
}

use actix_web::{App, HttpServer};
use sea_orm_migration::prelude::*;

mod config;
mod handlers;
mod models;
mod routes;
mod services;

use config::database::DatabaseConfig;
use routes::main_routes;
use crate::routes::file_routes;

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    println!("서버를 시작합니다: http://localhost:8080");

    // 데이터베이스 연결
    let db = DatabaseConfig::connect()
        .await
        .expect("데이터베이스 연결 실패");

    // 마이그레이션 실행 - MigratorTrait을 사용
    migration::Migrator::up(&db, None)
        .await
        .expect("마이그레이션 실행 실패");

    println!("데이터베이스 연결 및 마이그레이션 완료");

    HttpServer::new(move || {
        App::new()
            .app_data(actix_web::web::Data::new(db.clone()))
            .service(
                main_routes::main_routes()
                    .service(file_routes::file_routes())
            )
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}

use actix_web::{App, HttpServer};
use sea_orm_migration::prelude::*;

mod config;
mod handlers;
mod models;
mod routes;
mod services;

use config::database::DatabaseConfig;
use routes::main_routes;
use crate::routes::file_routes;

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    println!("서버를 시작합니다: http://localhost:8080");

    // 데이터베이스 연결
    let db = match DatabaseConfig::connect().await {
        Ok(connection) => {
            println!("✅ 데이터베이스 연결 성공!");
            connection
        }
        Err(e) => {
            eprintln!("❌ 데이터베이스 연결 실패: {:?}", e);
            eprintln!("현재 작업 디렉토리: {:?}", std::env::current_dir().unwrap());
            std::process::exit(1);
        }
    };

    // 마이그레이션 실행 - MigratorTrait을 사용
    match migration::Migrator::up(&db, None).await {
        Ok(_) => println!("✅ 마이그레이션 완료!"),
        Err(e) => {
            eprintln!("❌ 마이그레이션 실행 실패: {:?}", e);
            std::process::exit(1);
        }
    }

    println!(" 데이터베이스 연결 및 마이그레이션 완료");

    HttpServer::new(move || {
        App::new()
            .app_data(actix_web::web::Data::new(db.clone()))
            .service(
                main_routes::main_routes()
                    .service(file_routes::file_routes())
            )
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}

use sea_orm::entity::prelude::*;
use sea_orm::Set;
use serde::{Deserialize, Serialize};
use uuid::Uuid;

#[derive(Clone, Debug, PartialEq, DeriveEntityModel, Eq, Serialize, Deserialize)]
#[sea_orm(table_name = "file")]
pub struct Model {
    #[sea_orm(primary_key, auto_increment = false)]
    pub saved_file_name: String,
    pub original_file_name: String,
    pub file_size: i64,
    pub status: String,
    pub created_at: chrono::DateTime<chrono::Utc>,
    pub updated_at: chrono::DateTime<chrono::Utc>,
}

#[derive(Copy, Clone, Debug, EnumIter, DeriveRelation)]
pub enum Relation {}

impl ActiveModelBehavior for ActiveModel {
    fn new() -> Self {
        Self {
            saved_file_name: Set(Uuid::now_v7().to_string()),
            original_file_name: Set(String::new()),
            file_size: Set(0),
            status: Set("pending".to_string()),
            created_at: Set(chrono::Utc::now()),
            updated_at: Set(chrono::Utc::now()),
        }
    }
}

impl Model {
    /// 새로운 파일 모델 생성 (UUID v7 자동 생성)
    pub fn new_with_uuid(
        original_file_name: String,
        file_size: i64,
        status: String,
    ) -> ActiveModel {
        ActiveModel {
            saved_file_name: Set(Uuid::now_v7().to_string()),
            original_file_name: Set(original_file_name),
            file_size: Set(file_size),
            status: Set(status),
            created_at: Set(chrono::Utc::now()),
            updated_at: Set(chrono::Utc::now()),
        }
    }

    /// UUID v7 값 검증 함수
    pub fn validate_uuid_v7(&self) -> bool {
        match Uuid::parse_str(&self.saved_file_name) {
            Ok(uuid) => {
                // UUID v7 버전 확인 (version 7)
                uuid.get_version() == Some(uuid::Version::SortRand)
            }
            Err(_) => false,
        }
    }

    /// 새로운 UUID v7 생성 및 반환
    pub fn generate_uuid_v7() -> String {
        Uuid::now_v7().to_string()
    }
}

pub mod file;

