use actix_web::{web, Scope};
use crate::handlers::file_handlers;

pub fn file_routes() -> Scope {
    web::scope("/files")
        .route("/download", web::get().to(file_handlers::download))
        .route("/upload/init", web::get().to(file_handlers::init))
        .route("/upload/chunk", web::post().to(file_handlers::chunk))
        .route("/upload/complete", web::post().to(file_handlers::complete))
        .route("/upload/cancel", web::post().to(file_handlers::cancel))
        .route("/upload/status", web::get().to(file_handlers::status))
}

use actix_web::{web, Scope};
use crate::handlers::file_handlers;

pub fn file_routes() -> Scope {
    web::scope("/files")
        .route("/download/{sessionId}", web::get().to(file_handlers::download))
        .route("/upload/init", web::get().to(file_handlers::init))
        .route("/upload/chunk", web::post().to(file_handlers::chunk))
        .route("/upload/complete", web::post().to(file_handlers::complete))
        .route("/upload/cancel", web::post().to(file_handlers::cancel))
        .route("/upload/status", web::get().to(file_handlers::status))
}

use actix_web::{web, Scope};
use crate::handlers::main_handlers;

pub fn main_routes() -> Scope {
    web::scope("/api")
        .route("/hello", web::get().to(main_handlers::hello))
        .route("/welcome/{name}", web::get().to(main_handlers::welcome))
        .route("/users", web::post().to(main_handlers::create_user))
        .route("/message", web::post().to(main_handlers::update_message))
}

